package dev.dsmp.economy.text;

import dev.dsmp.economy.*;
import com.google.gson.Gson;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;
import java.nio.file.Path;
import static org.junit.jupiter.api.Assertions.*;

class LineStyleTest {
    @Test void oldBoxesKeepTheirTextAndReceiveEmptyOptionalStyles(){var b=new Gson().fromJson("{\"text\":\"one\\ntwo\",\"font\":2}",TextBox.class);b.validate();assertTrue(b.lineStyles.isEmpty());assertEquals(2,b.font);b.font=3;b.validate();b.font=4;assertThrows(IllegalArgumentException.class,b::validate);}
    @Test void lineSettingsPersistIndependentlyAndCancelDeepCopies(@TempDir Path dir)throws Exception{
        var cfg=new TrackerConfig();var b=new TextBox();b.text="First\nSecond";cfg.textBoxes.add(b);var s=b.editLine(1);s.custom=true;s.font=3;s.gradient=2;s.startColor=0xABCDEF;s.endColor=0x123456;s.image="builtin:cards";s.shape=1;s.note="Tie = DD";s.textSize=1.4f;var editor=new TextBoxEditor(cfg);s.note="Changed";editor.cancel();assertEquals("Tie = DD",cfg.textBoxes.getFirst().style(1).note);assertNotSame(s,cfg.textBoxes.getFirst().style(1));
        var store=new LocalStore(dir);store.saveConfig(cfg);var loaded=store.loadConfig().textBoxes.getFirst();assertEquals("First\nSecond",loaded.text);assertFalse(loaded.style(0).custom);assertEquals(3,loaded.style(1).font);assertEquals("builtin:cards",loaded.style(1).image);assertEquals(0xABCDEF,loaded.style(1).startColor);assertEquals(1.4f,loaded.style(1).textSize);
    }
    @Test void shorteningContentTrimsOnlyRemovedLineStylesAndBadEditsAreAtomic(){var cfg=new TrackerConfig();var editor=new TextBoxEditor(cfg);var b=editor.add();b.text="A\nB\nC";b.editLine(0).note="kept";b.editLine(2).note="removed";editor.fields("A\\nB","FFFFFF","000000");assertEquals(2,b.lineStyles.size());assertEquals("kept",b.style(0).note);assertThrows(IllegalArgumentException.class,()->editor.fields("Changed","BAD","000000"));assertEquals("A\nB",b.text);assertEquals("kept",b.style(0).note);}
    @Test void presetUsesTheProvidedUserNameAndStylesOnlyTheChosenBox(){var cfg=new TrackerConfig();var editor=new TextBoxEditor(cfg);var first=editor.add();first.text="Keep me";editor.add();editor.reference("MyAccount");var b=editor.selected();assertTrue(b.text.startsWith("IGN MyAccount"));assertEquals(13,b.lines().length);assertEquals(13,b.lineStyles.size());assertEquals(3,b.font);assertEquals(0,b.backgroundStyle);assertEquals(1,b.style(3).shape);assertEquals("builtin:cards",b.style(3).image);assertTrue(b.style(3).bullet);assertEquals("Keep me",first.text);cfg.validate();}
    @Test void geometryIncludesImageNotesBulletAndIndependentTextSize(){var b=new TextBox();b.text="A\nBBBB";b.font=0;var a=b.editLine(0);a.custom=true;a.font=3;a.textSize=2;a.image="builtin:cards";a.iconSize=20;a.bullet=true;a.shape=1;a.note="Tie";var l=StyledTextLayout.measure(b,(text,font)->text.length()*(font==3?8:6));var r=l.rows().getFirst();assertEquals(3,r.font());assertEquals(16+10+26+16+21,r.width());assertTrue(r.height()>=32);assertTrue(l.rows().get(1).y()>=r.y()+r.height()+3);assertEquals(0,l.rows().get(1).font());assertTrue(r.noteX()>r.textX());assertEquals(r.width(),l.width());}
    @Test void gradientsCanInheritOrOverrideWithoutChangingOtherLines(){var b=new TextBox();b.text="A\nB";b.gradient=2;b.startColor=0x112233;var second=b.editLine(1);second.custom=true;second.font=3;second.gradient=1;second.startColor=0xAABBCC;var l=StyledTextLayout.measure(b,(text,font)->6);assertEquals(2,l.rows().getFirst().gradient());assertEquals(0x112233,l.rows().getFirst().start());assertEquals(1,l.rows().get(1).gradient());assertEquals(0xAABBCC,l.rows().get(1).start());assertEquals(0x112233,b.startColor);}
    @Test void richRowsFitTheSmallEditorViewport(){var b=new TextBox();b.text=String.join("\n",java.util.Collections.nCopies(24,"Wide row"));for(int i=0;i<24;i++){var s=b.editLine(i);s.shape=1;s.textSize=2.5f;s.iconSize=32;s.image="builtin:cards";}var l=StyledTextLayout.measure(b,(text,font)->text.length()*7);var bounds=TextLayout.bounds(b,new TextLayout.Measure(java.util.List.of(),l.width(),l.height()),320,240,true);assertTrue(bounds.x()+bounds.width()<=320);assertTrue(bounds.y()+bounds.height()<=240);}
    @Test void invalidLineContentPathsColorsAndBoundsAreRejected(){var s=new LineStyle();s.validate();for(String image:new String[]{"https://example.com/a.png","file:../outside.png","file:.hidden.png","file:a..b.png","file:/tmp/a.png"}){s.image=image;assertThrows(IllegalArgumentException.class,s::validate);}s.image="builtin:cards";s.note="A\nB";assertThrows(IllegalArgumentException.class,s::validate);s.note="";s.startColor=0xFF112233;assertThrows(IllegalArgumentException.class,s::validate);s.startColor=0;s.textSize=Float.NaN;assertThrows(IllegalArgumentException.class,s::validate);s.textSize=1;s.iconSize=100;assertThrows(IllegalArgumentException.class,s::validate);}
}
